0 & \mbox{if } i \neq 0
\end{cases}} .
\end{align*}
$$

2. Compute

$$
\begin{align*}
\lim_{\tau \rightarrow \infty} f_i
& = \lim_{\tau \rightarrow \infty} \frac{\exp \left( z_i / \tau \right)}
{\sum_{j = 0}^{N-1} \exp \left( z_j / \tau \right)} \\
& = \frac{1}{\sum_{j = 0}^{N-1} 1} \\
& = \boxed{\frac{1}{N}} .
\end{align*}
$$
